package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	var n, k, l, c, d, p, nl, np int
	fmt.Fscan(in, &n, &k, &l, &c, &d, &p, &nl, &np)

	totalDrink := k * l
	totalLimeSlices := c * d

	toastsByDrink := totalDrink / nl
	toastsByLimes := totalLimeSlices
	toastsBySalt := p / np

	minToasts := toastsByDrink
	if toastsByLimes < minToasts {
		minToasts = toastsByLimes
	}
	if toastsBySalt < minToasts {
		minToasts = toastsBySalt
	}

	fmt.Println(minToasts / n)
}

